inline const SKQ *GetSKQ(const void *buf) {
  return ::flatbuffers::GetRoot<SKQ>(buf);
}

inline const SKQ *GetSizePrefixedSKQ(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<SKQ>(buf);
}

inline const char *SKQIdentifier() {
  return "$SKQ";
}

inline bool SKQBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, SKQIdentifier());
}

inline bool SizePrefixedSKQBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, SKQIdentifier(), true);
}

template <bool B = false>
inline bool VerifySKQBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<SKQ>(SKQIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedSKQBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<SKQ>(SKQIdentifier());
}

inline void FinishSKQBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<SKQ> root) {
  fbb.Finish(root, SKQIdentifier());
}

inline void FinishSizePrefixedSKQBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<SKQ> root) {
  fbb.FinishSizePrefixed(root, SKQIdentifier());
}

inline std::unique_ptr<SKQT> UnPackSKQ(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<SKQT>(GetSKQ(buf)->UnPack(res));
}

inline std::unique_ptr<SKQT> UnPackSizePrefixedSKQ(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<SKQT>(GetSizePrefixedSKQ(buf)->UnPack(res));
}

